"""Generate manuscript numbers and a task-separated report from saved results."""
from pathlib import Path
import json,sys
import numpy as np
root=Path(__file__).resolve().parents[1];out=root/'artifacts/validation_v2'
comparison=json.loads((out/'comparison.json').read_text())
macros={};lines=['# Validação adicional: segunda análise exploratória','','O teste anterior já foi consultado. Não houve escolha de corte ou ajuste de hiperparâmetros pelas métricas desse teste.','','## Predição direta do indicador global','','| Método | MAE RMS (m/s²) | Acurácia | Macro-F1 |','|---|---:|---:|---:|']
for method,prefix in [('constant_log_rms','Constant'),('road_only','Road'),('ridge_features','Ridge'),('LSTM_head','Lstm')]:
 rows=[r for r in comparison if r['experiment']=='all' and r['method']==method and r['class']=='ALL']
 mean={k:float(np.mean([r[k] for r in rows])) for k in ['aw_mae','accuracy','macro_f1']}
 lines.append(f"| {method} | {mean['aw_mae']:.3f} | {mean['accuracy']:.3f} | {mean['macro_f1']:.3f} |")
 for metric,label,scale,digits in [('aw_mae','MAE',1,3),('accuracy','Acc',100,1),('macro_f1','Fone',1,3)]:macros[prefix+label]=f"{mean[metric]*scale:.{digits}f}".replace('.',',')
lines+=['','A regressão simples de amplitude da pista alcançou 96,7%; a de oito características, 100%, contra 94,4% da LSTM. Não foi demonstrada vantagem da LSTM na classificação. Os resultados não validam conforto humano.','','## Trajetórias','','O ARX mantém menor erro de deslocamento: 0,488 mm contra 0,669 mm da LSTM global. A cabeça de RMS é uma tarefa distinta da trajetória, sem consistência física imposta entre elas.','','## Robustez do alvo','','Com processamento igual, 53/54 janelas de C no teste mudam o rótulo de desconforto ao reduzir o corte de 80 para 40 Hz. O alvo é sensível à banda; o corte principal foi mantido para preservar o experimento original. Energia acima de 20 Hz não é prova de ruído, mas exige cautela.','','## Repetições','','As 270 janelas globais são 90 fases distintas, repetidas três vezes. São reportadas métricas por passagem e após média por fase; não se assumem 270 ensaios independentes. Desvios entre sementes descrevem variação do treinamento.','','Gráficos: learning_curves, rms_scatter, errors_by_class, errors_by_horizon, filter_sensitivity e repetition_summary, em figures/validation_v2.']
(root/'docs/RESULTADOS_V2.md').write_text('\n'.join(lines)+'\n')
(root/'paper/results_v2.tex').write_text('% Generated by scripts/report_v2.py from comparison.json\n'+'\n'.join('\\newcommand{\\'+k+'}{'+v+'}' for k,v in macros.items())+'\n')
print('Report and traceable LaTeX numbers generated')
